pushCandidate(j.sender);
pushCandidate(j.Sender);

const headers = j.headers || j.payload?.headers || j.raw?.headers;
pushCandidate(headerValue(headers, 'from'));
pushCandidate(headerValue(headers, 'From'));
pushCandidate(headerValue(headers, 'reply-to'));
pushCandidate(headerValue(headers, 'Reply-To'));

