const item = $input.first();
const prev = $('Consolidate HubSpot Results').first().json;
let raw = item.json.message?.content
  || item.json.text
  || item.json.choices?.[0]?.message?.content
  || item.json.output
  || item.json;

if (typeof raw === 'string') {
  const cleaned = raw.replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
  try { raw = JSON.parse(cleaned); } catch (e) {
    raw = {
      category: 'General Support',
      intent: 'Unknown',
      priority: 'Medium',
      sentiment: 'Neutral',
      summary: cleaned.slice(0, 500),
      suggested_reply: 'Thank you for contacting support. We have received your request and will follow up shortly.',
      issue_title: prev.subject || 'Support request'
    };
  }
}

const allowedCategories = ['Billing','Technical','Sales','Account','Feature Request','General Support'];
const allowedPriorities = ['Critical','High','Medium','Low'];

const category = allowedCategories.includes(raw.category) ? raw.category : 'General Support';
const priority = allowedPriorities.includes(raw.priority) ? raw.priority : 'Medium';

const ai = {
  category,
  intent: raw.intent || 'General Inquiry',
  priority,
  sentiment: raw.sentiment || 'Neutral',
  summary: raw.summary || '',
  suggested_reply: raw.suggested_reply || '',
  issue_title: raw.issue_title || prev.subject || 'Support request'
};

return [{ json: { ...prev, ai } }];

const item = $input.first().json;
const minutes = item.config.slaPolicy.priorities[item.ai.priority]?.responseMinutes || 480;
const slaDue = new Date(Date.now() + minutes * 60 * 1000).toISOString();
const jiraPriority = item.config.slaPolicy.priorities[item.ai.priority]?.jiraPriorityName || 'Medium';
const teamMap = item.config.teamAssignment.categoryToTeam[item.ai.category]
  || item.config.teamAssignment.fallback;

return [{
  json: {
    ...item,
    slaDue,
    slaMinutes: minutes,
    jiraPriorityName: jiraPriority,
    assignedTeam: teamMap,
    slaNotified: false
  }
}];

const d = $input.first().json;

// --- Atlassian Document Format helpers ---
function t(str, marks) {
  const node = { type: 'text', text: String(str ?? '') };
  if (marks && marks.length) node.marks = marks;
  return node;
}
function strong(str) {
  return t(str, [{ type: 'strong' }]);
}
function p(...nodes) {
  const content = nodes.flat().filter(n => n && (n.text !== undefined || n.type));
  if (!content.length) return { type: 'paragraph', content: [t(' ')] };
  return { type: 'paragraph', content };
}
function h(level, str) {
  return { type: 'heading', attrs: { level }, content: [t(str)] };
}
function li(label, value) {
  return {
    type: 'listItem',
    content: [p(strong(`${label}: `), t(value == null || value === '' ? 'N/A' : value))]
  };
}
function ul(items) {
  return { type: 'bulletList', content: items };
}
function paragraphsFromText(text) {
  const raw = String(text || '').trim() || '(empty)';
  return raw.split(/\n+/).map(line => p(t(line.slice(0, 5000))));
}

// --- Jira date formats ---
function toJiraDateTime(iso) {
  if (!iso) return null;
  const dt = new Date(iso);
  if (Number.isNaN(dt.getTime())) return null;
  // Date Time Picker expects +0000, not trailing Z
  return dt.toISOString().replace(/\.\d{3}Z$/, '.000+0000').replace(/Z$/, '+0000');
}
function toJiraDate(iso) {
  if (!iso) return null;
  const dt = new Date(iso);
  if (Number.isNaN(dt.getTime())) return null;
  return dt.toISOString().slice(0, 10);
}
function isConfiguredField(id) {
  return typeof id === 'string' && id.startsWith('customfield_') && !id.includes('REPLACE_');
}

// Prefer CRM enrichment for display name when available
const displayName = (d.crm?.customerName && String(d.crm.customerName).trim())
  || d.customerName
  || 'N/A';
const displayEmail = d.email || 'N/A';
const channel = d.channel || 'N/A';

// WhatsApp often has LID not a real phone — omit Phone line for that channel only
const customerItems = [
  li('Name', displayName === 'N/A' ? 'N/A' : displayName),
  li('Email', displayEmail),
];
if (String(d.channel || '').toLowerCase() !== 'whatsapp') {
  customerItems.push(li('Phone', d.phone || 'N/A'));
}
customerItems.push(li('Channel', channel));
const customerList = ul(customerItems);

const crmList = ul([
  li('Found', d.crm?.found ? 'Yes' : 'No'),
  li('Customer Type', d.crm?.customerType || 'N/A'),
  li('Company', d.crm?.company || 'N/A'),
  li('Subscription', d.crm?.subscription || 'N/A'),
  li('Customer Status', d.crm?.customerStatus || 'N/A'),
  li('Previous Tickets', d.crm?.previousTickets || 'N/A'),
  li('HubSpot Contact ID', d.crm?.hubspotContactId || 'N/A')
]);

const aiList = ul([
  li('Category', d.ai?.category || 'N/A'),
  li('Intent', d.ai?.intent || 'N/A'),
  li('Priority', d.ai?.priority || 'N/A'),
  li('Sentiment', d.ai?.sentiment || 'N/A'),
  li('Summary', d.ai?.summary || 'N/A')
]);

const internalList = ul([
  li('Dedupe Key', d.dedupeKey || 'N/A'),
  li('Received At', d.receivedAt || 'N/A'),
  li('SLA Due', d.slaDue || 'N/A'),
  li('Assigned Team', d.assignedTeam?.teamName || 'N/A')
]);

const jiraDescriptionAdf = {
  type: 'doc',
  version: 1,
  content: [
    h(2, 'Customer Information'),
    customerList,
    h(2, 'CRM Information (HubSpot)'),
    crmList,
    h(2, 'AI Analysis'),
    aiList,
    h(2, 'Original Customer Message'),
    p(strong('Subject: '), t(d.subject || '(no subject)')),
    ...paragraphsFromText(d.message),
    h(2, 'Suggested Reply'),
    ...paragraphsFromText(d.ai?.suggested_reply || ''),
    h(2, 'Internal'),
    internalList
  ]
};

const plainLines = [
  'Customer Information',
  `Name: ${displayName}`,
  `Email: ${displayEmail}`,
  '',
  'AI Analysis',
  `Category: ${d.ai?.category}`,
  `Priority: ${d.ai?.priority}`,
  `SLA Due: ${d.slaDue || ''}`
];

const labelSafe = String(d.dedupeKey || '')
  .toLowerCase()
  .replace(/[^a-z0-9:_-]/g, '-')
  .slice(0, 255);
const categoryLabel = String(d.ai?.category || 'general')
  .toLowerCase()
  .replace(/\s+/g, '-');

// Custom fields to set at CREATE time (more reliable than only POST-stamp)
const cf = d.config?.slaPolicy?.jira?.customFields || {};
const jiraExtraFields = {};
const jiraDateTimeSla = toJiraDateTime(d.slaDue);
const jiraDateOnly = toJiraDate(d.slaDue);

if (isConfiguredField(cf.slaDue) && jiraDateTimeSla) {
  jiraExtraFields[cf.slaDue] = jiraDateTimeSla;
}
if (isConfiguredField(cf.slaNotified)) {
  jiraExtraFields[cf.slaNotified] = { value: 'false' }; // Select List (single choice)
}
if (isConfiguredField(cf.aiCategory) && d.ai?.category) {
  jiraExtraFields[cf.aiCategory] = String(d.ai.category);
}
if (isConfiguredField(cf.aiPriority) && d.ai?.priority) {
  jiraExtraFields[cf.aiPriority] = String(d.ai.priority);
}
if (isConfiguredField(cf.dedupeKey) && d.dedupeKey) {
  jiraExtraFields[cf.dedupeKey] = String(d.dedupeKey).slice(0, 255);
}
if (isConfiguredField(cf.channel) && d.channel) {
  jiraExtraFields[cf.channel] = String(d.channel);
}

// System Due date (sidebar "Due date") — date-only
if (jiraDateOnly) {
  jiraExtraFields.duedate = jiraDateOnly;
}

// Preserve improved display name on payload for Slack
const customerNameOut = displayName === 'N/A' ? (d.customerName || '') : displayName;

return [{
  json: {
    ...d,
    customerName: customerNameOut || d.customerName || '',
    jiraSummary: (d.ai?.issue_title || d.subject || 'Support request').slice(0, 255),
    jiraDescriptionAdf,
    jiraDescription: plainLines.join('\n'),
    jiraExtraFields,
    jiraDateTimeSla,
    jiraDateOnly,
    jiraLabels: [
      'ai-triage',
      categoryLabel,
      `priority-${String(d.ai?.priority || 'medium').toLowerCase()}`,
      `channel-${d.channel || 'unknown'}`,
      labelSafe.startsWith('dedupe-') ? labelSafe : `dedupe-${labelSafe}`.slice(0, 255)
    ].filter(Boolean),
    dedupeLabel: labelSafe.startsWith('dedupe-') ? labelSafe : `dedupe-${labelSafe}`.slice(0, 255)
  }
}];

const prev = $('Generate Jira Payload').first().json;
const search = $input.first().json;
const issues = search.issues || search.data?.issues || [];
const duplicate = Array.isArray(issues) && issues.length > 0;
const existing = duplicate ? issues[0] : null;
const baseUrl = (prev.config?.jiraBaseUrl || prev.config?.teamAssignment?.jiraBaseUrl || 'https://intuzdev5.atlassian.net').replace(/\/$/, '');
const key = existing?.key || null;
const jiraUrl = key ? `${baseUrl}/browse/${key}` : '';
return [{
  json: {
    ...prev,
    duplicate,
    existingJiraKey: key,
    jiraKey: key,
    jiraUrl
  }
}];

