}

const upstream = $input.first().json || {};
const created = {
  ...base,
  ...upstream,
  jiraKey: base.jiraKey || upstream.jiraKey || upstream.key,
  jiraId: base.jiraId || upstream.jiraId || upstream.id,
  ai: base.ai || upstream.ai,
  config: base.config || upstream.config,
  crm: base.crm || upstream.crm,
  assignedTeam: base.assignedTeam || upstream.assignedTeam,
