  dedupeKey: base.dedupeKey || upstream.dedupeKey,
  slaDue: base.slaDue || upstream.slaDue,
  channel: base.channel || upstream.channel
};

delete created.error;
delete created._doSlaStamp;
delete created._slaStampBody;

// In-line NoOp at the start of shared triage (same role as the old sub-workflow trigger).
const trigger = $('Hold Binary For Upload').first();
const meta = created.attachments || [];
const binary = trigger.binary || {};
const binaryKeys = Object.keys(binary);

const issueKey = created.jiraKey || created.key || created.issueKey || created.existingJiraKey;
const issueId = created.jiraId || created.id || created.issueId;

if (!meta.length || !binaryKeys.length) {
  return [{
    json: {
      ...created,
      jiraKey: issueKey,
      jiraId: issueId,
      attachmentsUploaded: 0,
      skipAttachments: true,
      skipReason: !meta.length ? 'no-attachment-meta' : 'no-binary-on-hold-node',
      binaryKeys
    }
  }];
}

const items = [];
for (const att of meta) {
  const key = att.binaryPropertyName;
  if (!binary[key]) continue;
  items.push({
    json: {
      ...created,
      jiraKey: issueKey,
      jiraId: issueId,
      uploadFilename: att.filename,
      uploadKind: att.kind,
      skipAttachments: false
    },
    binary: { data: binary[key] }
  });
}

if (!items.length) {
  return [{
    json: {
      ...created,
      jiraKey: issueKey,
      jiraId: issueId,
      attachmentsUploaded: 0,
      skipAttachments: true,
      skipReason: 'binary-key-mismatch',
      binaryKeys,
      metaKeys: meta.map(a => a.binaryPropertyName)
    }
  }];
}
return items;

// Normalize payload for Slack (single or multi attachment path)
const item = $input.first().json;
let base = item;
