const prev = $('Merge Jira Create Result4').first().json;
const cf = prev.config?.slaPolicy?.jira?.customFields || {};

function isConfigured(id) {
  if (!id || typeof id !== 'string') return false;
  if (id.includes('REPLACE_')) return false;
  if (!id.startsWith('customfield_')) return false;
  return true;
}
function toJiraDateTime(iso) {
  if (!iso) return null;
  const dt = new Date(iso);
  if (Number.isNaN(dt.getTime())) return null;
  return dt.toISOString().replace(/\.\d{3}Z$/, '.000+0000').replace(/Z$/, '+0000');
}
function toJiraDate(iso) {
  if (!iso) return null;
  const dt = new Date(iso);
  if (Number.isNaN(dt.getTime())) return null;
  return dt.toISOString().slice(0, 10);
}

const stampFields = {};
const jiraDateTimeSla = toJiraDateTime(prev.slaDue || prev.jiraDateTimeSla);
const jiraDateOnly = toJiraDate(prev.slaDue || prev.jiraDateOnly);

if (isConfigured(cf.slaDue) && jiraDateTimeSla) stampFields[cf.slaDue] = jiraDateTimeSla;
if (isConfigured(cf.slaNotified)) stampFields[cf.slaNotified] = { value: 'false' }; // Select List (single choice)
if (isConfigured(cf.aiCategory) && prev.ai?.category) stampFields[cf.aiCategory] = String(prev.ai.category);
if (isConfigured(cf.aiPriority) && prev.ai?.priority) stampFields[cf.aiPriority] = String(prev.ai.priority);
if (isConfigured(cf.dedupeKey) && prev.dedupeKey) stampFields[cf.dedupeKey] = String(prev.dedupeKey).slice(0, 255);
if (isConfigured(cf.channel) && prev.channel) stampFields[cf.channel] = String(prev.channel);
// Always refresh system Due date so Details panel shows a date
if (jiraDateOnly) stampFields.duedate = jiraDateOnly;

const doStamp = Object.keys(stampFields).length > 0 && !!prev.jiraKey;

return [{
  json: {
    ...prev,
    _doSlaStamp: doStamp,
    _slaStampBody: doStamp ? { fields: stampFields } : null,
    slaStampSkipped: !doStamp,
    slaStampFieldCount: Object.keys(stampFields).length,
    jiraDateTimeSla,
    jiraDateOnly
  }
}];

// Always continue with ticket context even if Jira stamp HTTP returned error/empty
const prev = $('Prepare SLA Stamp3').first().json;
const stampRes = $input.first().json || {};
const failed = !!(stampRes.error || stampRes.message?.includes?.('error'));
return [{
  json: {
    ...prev,
    slaStamped: !failed && prev._doSlaStamp === true,
    slaStampError: stampRes.error || null,
    _doSlaStamp: undefined,
    _slaStampBody: undefined
  }
}];

const prev = $('Prepare Attachments4').first().json;
const upload = $input.first().json || {};
const uploadedOk = !upload.error;
return [{
  json: {
    ...prev,
    attachmentsUploaded: uploadedOk ? 1 : 0,
    skipAttachments: false,
    attachmentUploadError: upload.error || null
  }
}];

// False branch: ticket fields already present on input — pass through.
const ticket = $input.item.json;
if (!ticket.jiraKey) {
  throw new Error('Missing jiraKey on no-raise path');
}
return { json: { ...ticket } };

// Stable per-ticket result (item count should match breached tickets)
const key = $json.jiraKey || $('Split Breached Issues1').item.json.jiraKey || 'unknown';
const err = $json.error || $json.message || null;
return {
  json: {
    jiraKey: key,
    markStatus: err ? 'error' : 'ok',
    markError: err ? String(err).slice(0, 500) : null,
    processedAt: new Date().toISOString()
  }
};

// Mirrors config/sla-policy.json + WF-04 (KAN / customfield_1010x)
const SLA_POLICY = {
  checkIntervalMinutes: 10,
  raisePriorityOnBreach: true,
  slack: {
    triageChannel: '#support-triage',
    slaChannel: '#support-sla',
    errorChannel: '#support-ops-errors',
    managerUserId: 'REPLACE_MANAGER_SLACK_USER_ID'
  },
  priorities: {
    Critical: { responseMinutes: 30, jiraPriorityName: 'Highest' },
    High: { responseMinutes: 120, jiraPriorityName: 'High' },
    Medium: { responseMinutes: 480, jiraPriorityName: 'Medium' },
    Low: { responseMinutes: 1440, jiraPriorityName: 'Low' }
  },
  priorityEscalationOrder: ['Low', 'Medium', 'High', 'Critical'],
  jira: {
    customFields: {
      slaDue: 'customfield_10106',
      slaNotified: 'customfield_10107',
      aiCategory: 'customfield_10108',
      aiPriority: 'customfield_10109',
      dedupeKey: 'customfield_10110',
      channel: 'customfield_10111'
    },
    labels: { slaBreached: 'sla-breached', dedupePrefix: 'dedupe-' }
  }
};

const TEAM = {
  projectKey: 'KAN',
  jiraBaseUrl: 'https://intuzdev5.atlassian.net'
};

const slaDueCf = 'cf[10106]';
const slaNotifiedCf = 'cf[10107]';

const jql = [
  `project = ${TEAM.projectKey}`,
  'resolution = Unresolved',
  `${slaDueCf} <= now()`,
  `(${slaNotifiedCf} is EMPTY OR ${slaNotifiedCf} = "false")`
].join(' AND ') + ` ORDER BY ${slaDueCf} ASC`;

return [{
  json: {
    config: {
      slaPolicy: SLA_POLICY,
      projectKey: TEAM.projectKey,
      jiraBaseUrl: TEAM.jiraBaseUrl,
      jiraProjectKey: TEAM.projectKey
    },
    jiraBaseUrl: TEAM.jiraBaseUrl,
    jql,
    now: new Date().toISOString()
  }
}];

const cfg = $('Load SLA Config1').first().json.config;
const search = $input.first().json;
const issues = search.issues || [];

if (!issues.length) {
  return [];
}

const jiraNames = ['Low', 'Medium', 'High', 'Highest'];
const f = cfg.slaPolicy.jira.customFields;

function fieldVal(fields, id) {
  const v = fields[id];
  if (v == null) return null;
  if (typeof v === 'object' && v.value !== undefined) return v.value;
  return v;
}

return issues.map((issue, index) => {
  const fields = issue.fields || {};
  const currentPriority = fields.priority?.name || 'Medium';
  let nextPriority = currentPriority;
  if (cfg.slaPolicy.raisePriorityOnBreach) {
    const idx = jiraNames.indexOf(currentPriority);
    if (idx >= 0 && idx < jiraNames.length - 1) nextPriority = jiraNames[idx + 1];
  }

  const slaDue = fieldVal(fields, f.slaDue) || fields.customfield_10106 || null;
  const ageMs = slaDue ? Date.now() - new Date(slaDue).getTime() : 0;
  const overdueMinutes = Math.max(0, Math.round(ageMs / 60000));
  const managerUserId = cfg.slaPolicy.slack.managerUserId || '';
  const hasManager =
    !!managerUserId &&
    !String(managerUserId).includes('REPLACE_') &&
    String(managerUserId).startsWith('U');

  // Full ticket payload — used by Slack + Jira branches independently (no rejoin).
  return {
    json: {
      _ticketIndex: index,
      config: cfg,
      jiraBaseUrl: cfg.jiraBaseUrl,
      jiraKey: issue.key,
      jiraId: issue.id,
      summary: fields.summary || '',
      status: fields.status?.name || '',
      currentPriority,
      nextPriority,
      assignee: fields.assignee?.displayName || 'Unassigned',
      aiPriority: fieldVal(fields, f.aiPriority) || fields.customfield_10109 || '',
      aiCategory: fieldVal(fields, f.aiCategory) || fields.customfield_10108 || '',
      slaDue,
      overdueMinutes,
      jiraUrl: `${cfg.jiraBaseUrl}/browse/${issue.key}`,
      raisePriority: cfg.slaPolicy.raisePriorityOnBreach === true && nextPriority !== currentPriority,
      managerUserId,
      hasManager,
      slaChannel: cfg.slaPolicy.slack.slaChannel
    }
  };
});

// Rehydrate ticket fields after HTTP wipe — use paired Split item, else index.
let ticket = null;
try {
  ticket = $('Split Breached Issues1').item.json;
} catch (e) {}
if (!ticket || !ticket.jiraKey) {
  const all = $('Split Breached Issues1').all();
  const idx = typeof $itemIndex === 'number' ? $itemIndex : 0;
  ticket = all[idx]?.json || null;
}
if (!ticket || !ticket.jiraKey) {
  throw new Error('Could not rehydrate ticket before Mark SLA Notified');
}
return { json: { ...ticket } };

const e = $input.first().json || {};
const exec = e.execution || {};
const wf = e.workflow || {};
const lastNode = exec.lastNodeExecuted || e.node?.name || e.node || 'unknown';
const err = exec.error || e.error || {};

let errorMessage = err.message || e.message || '';
if (!errorMessage && typeof err === 'string') errorMessage = err;
if (!errorMessage) errorMessage = 'Unknown error';

const errorDescription = err.description || err.stack || e.description || '';
const executionId = exec.id || e.executionId || e.id || '';
const workflowName = wf.name || e.workflowName || 'unknown';
const workflowId = wf.id || e.workflowId || '';

// Build a deep-link if n8n provides one; otherwise leave empty
const url = exec.url || e.url || '';

return [{
  json: {
    workflowName,
    workflowId,
    executionId,
    lastNode: typeof lastNode === 'object' ? (lastNode.name || String(lastNode)) : String(lastNode),
    errorMessage: String(errorMessage).slice(0, 1500),
    errorDescription: String(errorDescription).slice(0, 800),
    timestamp: new Date().toISOString(),
    url
  }
}];
